Task: Return base to the power k. base^0 is 1.
Signature: int power_up(int base, int k)

Student code:
```c
int multiply_int(int a, int b) {
    int product; // declare product variable (product starts at 0)
    product = (a * b); // multiply a and b and store in product
    return (product); // return the product value
}

int power_up(int base, int k) {
    int result; // declare result variable (result starts at 0)
    int i; // declare loop counter i (i starts at 0)
    result = 1; // set result to 1 to start multiplication
    for (; (i < k); i = (i + 1)) { // loop while i is less than k (i starts at 0)
        result = (multiply_int(result, base)); // multiply result by base each loop
    }
    return (result); // return the final result
}
```
